/* Reversible local review state; workflow gates affect demo completion only. */
state.reviewNotes??={};state.reviewCompletion??={};
function resultById(eid){return state.results.find(r=>r.eventId===eid)}
function reviewGate(pid){const pending=labAlerts(pid).filter(r=>!state.labReviews[r.eventId]);return{pending,hard:pending.some(r=>r.critical===true),mode:!pending.length?'ready':pending.some(r=>r.critical===true)?'hard':'soft'}}
function resultReviewButton(r){const reviewed=!!state.labReviews[r.eventId];return `<div class="reviewcontrol"><span class="pill ${reviewed?'':'amber'}">${reviewed?'Reviewed':'Unreviewed'}</span><button class="btn" onclick="reviewResult(decodeURIComponent('${encodeURIComponent(r.eventId)}'))">${reviewed?'Change / undo':'Review options'}</button>${state.reviewNotes[r.eventId]?'<small>Follow-up note recorded</small>':''}</div>`}
reviewResult=function(eid){const r=resultById(eid);if(!r)return;const reviewed=state.labReviews[eid];openDialog('Result review · '+esc(r.code),`<p><b>${esc(r.patientId)}</b> · ${esc(r.value)} ${esc(r.unit||'')} · ${esc(r.status)}</p><span class="pill ${reviewed?'':'amber'}">${reviewed?'Reviewed · '+esc(fmt(reviewed)):'Unreviewed'}</span><p style="margin-top:16px">Review status records that you checked this result. It does not resolve the clinical alert or approve treatment.</p><div class="reviewchoices"><button class="btn primary" ${reviewed?'disabled':''} onclick="setResultReview(decodeURIComponent('${encodeURIComponent(eid)}'),'reviewed')">Mark reviewed</button><button class="btn" ${!reviewed?'disabled':''} onclick="setResultReview(decodeURIComponent('${encodeURIComponent(eid)}'),'unreviewed')">Mark unreviewed / undo</button><button class="btn" onclick="closeDialog()">Leave unchanged / back</button></div><details><summary>Review later with a follow-up note</summary><form onsubmit="event.preventDefault();deferResultReview(decodeURIComponent('${encodeURIComponent(eid)}'),this)"><label class="field" style="margin-top:15px">Reason / follow-up<input name="reason" required maxlength="300" placeholder="For example: awaiting microbiology clarification"></label><button class="btn" type="submit">Save as unreviewed — review later</button></form></details>`)};
function setResultReview(eid,status){const r=resultById(eid);if(!r||!['reviewed','unreviewed'].includes(status))return;const prior=!!state.labReviews[eid];if(status==='reviewed')state.labReviews[eid]=new Date().toISOString();else delete state.labReviews[eid];delete state.reviewCompletion[r.patientId];closeDialog();save((status==='reviewed'?'Result marked reviewed':'Review undone; result returned to unreviewed')+'; previous state '+(prior?'reviewed':'unreviewed')+'; '+eid,r.patientId)}
function deferResultReview(eid,form){const r=resultById(eid),reason=String(new FormData(form).get('reason')||'').trim();if(!r||!reason)return;delete state.labReviews[eid];delete state.reviewCompletion[r.patientId];state.reviewNotes[eid]={reason,recordedAt:new Date().toISOString()};closeDialog();save('Result deferred as unreviewed: '+eid+'; reason: '+reason,r.patientId)}
resultTable=function(rows){if(!rows.length)return '<p>No results in this category.</p>';return `<div class="scroll"><table><thead><tr><th>Test</th><th>Result</th><th>Observed</th><th>Report / source</th><th>Review status & action</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.code)}</b></td><td>${esc(r.value)} ${esc(r.unit||'')} ${r.critical?'<span class="pill red">Lab flagged</span>':''}</td><td>${fmt(r.observedAt)}</td><td>${esc(r.status)}<div class="mini">${esc(r.source)} · ${esc(r.accession)}</div></td><td>${resultReviewButton(r)}</td></tr>`).join('')}</tbody></table></div>`};
alertCard=function(r){return `<div class="resultalert"><div><b>${r.code==='culture'?'Positive culture':esc(r.code)+' result requires review'}</b><p>${esc(r.value)} ${esc(r.unit||'')} · ${esc(r.status)} · SIMULATED</p><small>${r.critical?'Lab-flagged critical result · completion gate':'Contextual alert · review or document deferral'}</small></div>${resultReviewButton(r)}</div>`};
const detailBeforeReview=detail;detail=function(){let h=detailBeforeReview();if(!selected)return h;const done=state.reviewCompletion[id(selected)];return h.replace('<div class="assessmentactions">',`<div class="assessmentactions"><button class="btn" onclick="finishReview()">${done?'Review completion details':'Finish case review'}</button>`)};
function finishReview(){if(!selected)return;const pid=id(selected),gate=reviewGate(pid),done=state.reviewCompletion[pid];if(done&&gate.hard){delete state.reviewCompletion[pid];save('Prior demo completion invalidated by pending critical result',pid);finishReview();return}if(done){openDialog('Demo review completion',`<p>${esc(pid)} · ${esc(fmt(done.time))}</p><p>${esc(done.note)}</p><p>This records a local demo workflow, not clinical discharge or treatment authorization.</p><button class="btn" onclick="closeDialog()">Back to patient</button>`);return}if(gate.mode==='hard'){openDialog('Hard stop · demo review completion',`<span class="pill red">Critical flagged result remains unreviewed</span><p style="margin-top:16px">You cannot mark this demo review complete until the lab-flagged critical result is reviewed. You can still open all patient tabs and continue care documentation.</p><div class="actions"><button class="btn primary" onclick="closeDialog();changeTab('Laboratory')">Open results to review</button><button class="btn" onclick="closeDialog()">Leave incomplete / back</button></div>`);return}if(gate.mode==='soft'){openDialog('Soft stop · review pending',`<span class="pill amber">${gate.pending.length} contextual alert(s) unreviewed</span><p style="margin-top:16px">Review now, or finish the demo workflow with a documented deferral. Deferred results stay unreviewed and remain in the review queue.</p><form onsubmit="event.preventDefault();completeReviewWithReason(this)"><label class="field">Reason for continuing<input name="reason" required maxlength="300"></label><div class="actions"><button class="btn primary" type="submit">Continue with reason</button><button class="btn" type="button" onclick="closeDialog();changeTab('Laboratory')">Review now</button><button class="btn" type="button" onclick="closeDialog()">Back</button></div></form>`);return}completeDemoReview('All current result-linked alerts reviewed. No treatment or discharge authorization.')}
function completeReviewWithReason(form){const reason=String(new FormData(form).get('reason')||'').trim();if(!reason||!selected||reviewGate(id(selected)).hard)return;completeDemoReview('Deferred contextual result review: '+reason)}
function completeDemoReview(note){if(!selected||reviewGate(id(selected)).hard)return;const pid=id(selected);state.reviewCompletion[pid]={time:new Date().toISOString(),note};closeDialog();save('Demo case review completed; '+note,pid)}
